#[repr(C)]
pub struct smb_to_posix_error {
    pub smb_err: __u16,
    pub posix_code: i32,
}

/* The request was successful. */
pub const SUCCESS: u32 = 0x00;
/* Error is from the core DOS operating system set */
pub const ERRDOS: u32 = 0x01;
/* Error is generated by the file server daemon */
pub const ERRSRV: u32 = 0x02;
/* Error is a hardware error. */
pub const ERRHRD: u32 = 0x03;
/* Command was not in the "SMB" format. */
pub const ERRCMD: u32 = 0xFF;

/* The following error codes may be generated with the SUCCESS error class. */

/* The following error codes may be generated with the ERRDOS error class. */

pub const ERRbadfunc: u32 = 1; // -EINVAL
pub const ERRbadfile: u32 = 2; // -ENOENT
pub const ERRbadpath: u32 = 3; // -ENOTDIR
